(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,77129,a=>{"use strict";let n=[{slug:"urutan-goresan-hanzi",image:{src:"/brand/art/brush.webp",alt:{en:"Ink painting of a calligraphy brush drawing a single stroke",id:"Lukisan tinta kuas kaligrafi menarik satu goresan"}},sources:[{label:"Data urutan goresan: Make Me a Hanzi",url:"https://github.com/skishore/makemeahanzi"},{label:"Hanzi Writer - animasi goresan",url:"https://hanziwriter.org"}],faq:[{q:{en:"Why does stroke order matter?",id:"Kenapa urutan goresan penting?"},a:{en:"Three practical reasons: the HSK exam marks handwriting and wrong order shows, dictionary and phone handwriting input recognise characters by their stroke sequence, and the correct order is simply faster because it follows the most efficient hand movement.",id:"Tiga alasan praktis: ujian HSK menilai tulisan tangan dan urutan yang salah terlihat, kamus dan input tulisan tangan di HP mengenali karakter dari urutan goresannya, dan urutan yang benar memang lebih cepat karena mengikuti gerak tangan paling efisien."}},{q:{en:"What are the basic stroke order rules?",id:"Apa aturan dasar urutan goresan?"},a:{en:"Top to bottom, left to right, horizontal before vertical when they cross, outside before inside, close the box last, centre before wings on symmetrical characters, left-falling before right-falling, and dots last. When two rules collide, top-to-bottom and left-to-right usually win.",id:"Atas ke bawah, kiri ke kanan, mendatar sebelum tegak kalau bersilangan, luar sebelum dalam, penutup kotak paling akhir, tengah sebelum sayap pada karakter simetris, jatuh-kiri sebelum jatuh-kanan, dan titik paling akhir. Kalau dua aturan bertabrakan, atas-ke-bawah dan kiri-ke-kanan biasanya menang."}},{q:{en:"How do I check the correct stroke order?",id:"Bagaimana cara mengecek urutan goresan yang benar?"},a:{en:"Watch it animated rather than reading a static diagram. A printed sheet shows the finished shape; an animation shows the order and direction of every stroke, which is the part you are actually trying to learn.",id:"Lihat animasinya, bukan diagram diam. Lembar cetak memperlihatkan bentuk akhirnya; animasi memperlihatkan urutan dan arah tiap goresan, dan itulah yang sebenarnya sedang kamu pelajari."}}],date:"2026-08-07",title:{en:"Stroke order in Chinese: the 8 rules that cover almost everything",id:"Urutan goresan hanzi: 8 aturan dasar yang mencakup hampir semuanya"},description:{en:"The eight stroke-order rules that handle most Chinese characters, why order matters even though nobody sees you write, and how to check any character.",id:"Delapan aturan urutan goresan yang mencakup sebagian besar karakter Mandarin, kenapa urutannya penting, dan cara memeriksa karakter apa pun."},body:{en:"Stroke order looks like bureaucracy until you understand what it is for. Nobody is watching you write, and a character drawn in the wrong order can still look correct on the page. So why does it matter?\n\nBecause order is how the character gets stored in your memory. A character written in a consistent order becomes a single motor sequence - one thing to recall - rather than a picture you have to reconstruct stroke by stroke every time. It is the difference between remembering a phone number as a rhythm and remembering eleven separate digits. Learners who skip stroke order can usually recognise characters and struggle to produce them, which is exactly the gap that shows up when you have to write something without a keyboard.\n\nIt also makes paper dictionaries usable, since stroke-count and radical lookup both depend on counting strokes the standard way - and it makes handwriting input more reliable, because those systems are built around the order most people write in.\n\nThe eight rules below handle most characters you will meet as a beginner. They are not exceptionless, and the exceptions are worth learning one at a time rather than trying to systematise.\n\n1. Top to bottom. 三 is written as three horizontal strokes from the top down. This is the rule that overrides most others when they conflict.\n\n2. Left to right. 川 goes left stroke, middle, right. Combined with the first rule, this handles a surprising amount on its own.\n\n3. Horizontal before vertical when strokes cross. 十 is the horizontal first, then the vertical. So is 干, 士, and every character containing them.\n\n4. Outside before inside. 月 starts with the enclosing shape before the two inner horizontals. 同, 用 and 周 all follow this.\n\n5. Enclosures close last. 国 is written as the three sides of the box, then everything inside, then the bottom line seals it. Writing the full box first is the single most common beginner error.\n\n6. Centre before wings in symmetrical characters. 小 is the central hook, then left, then right. 水 and 承 follow the same shape.\n\n7. Left-falling before right-falling. 人 is the left-falling stroke then the right-falling one. This holds inside larger characters too - 文, 交, 这.\n\n8. Dots and minor strokes last. The dot in 玉 comes after the 王 beneath it. Small finishing strokes usually close a character rather than open it.\n\nThe rules conflict sometimes, and when they do, top-to-bottom and left-to-right generally win. 里 is a good test: the 日 on top comes first as a complete unit, then the 土 beneath it, rather than trying to write all the horizontals together.\n\nThe fastest way to internalise any of this is to write the character while watching the order, not to memorise the list. Every character on this site has an animated stroke order you can replay, and a practice mode that tells you when the order or direction is wrong - which is the part a static diagram cannot do.",id:"Urutan goresan terlihat seperti aturan birokrasi sampai kamu paham fungsinya. Tidak ada yang mengawasimu menulis, dan karakter yang ditulis dengan urutan salah pun bisa tetap terlihat benar di kertas. Jadi kenapa penting?\n\n## Kenapa urutan goresan penting\n\nKarena urutan adalah cara karakter itu tersimpan dalam ingatanmu. Karakter yang ditulis dengan urutan konsisten menjadi satu rangkaian gerak - satu hal yang perlu diingat - bukan gambar yang harus kamu susun ulang goresan demi goresan setiap kali. Bedanya seperti mengingat nomor telepon sebagai irama dibanding mengingat sebelas angka terpisah. Pelajar yang melewati urutan goresan biasanya bisa mengenali karakter tapi kesulitan menuliskannya - dan justru itu yang terasa saat kamu harus menulis tanpa papan ketik.\n\nUrutan juga membuat kamus cetak bisa dipakai, karena pencarian berdasarkan jumlah goresan maupun radikal sama-sama bergantung pada cara menghitung goresan yang standar - dan membuat input tulisan tangan lebih andal, karena sistemnya dibangun mengikuti urutan yang dipakai kebanyakan orang.\n\n## Delapan aturan urutan goresan hanzi\n\nDelapan aturan di bawah menangani sebagian besar karakter yang kamu temui sebagai pemula. Bukan tanpa pengecualian, dan pengecualiannya lebih baik dipelajari satu per satu daripada dipaksa masuk sistem.\n\n1. Atas ke bawah. 三 ditulis sebagai tiga goresan mendatar dari atas ke bawah. Aturan ini mengalahkan hampir semua aturan lain saat bertabrakan.\n\n2. Kiri ke kanan. 川 ditulis goresan kiri, tengah, lalu kanan. Digabung dengan aturan pertama, dua ini saja sudah menyelesaikan banyak karakter.\n\n3. Mendatar sebelum tegak kalau bersilangan. 十 dimulai dari goresan mendatar, baru yang tegak. Begitu juga 干, 士, dan setiap karakter yang memuatnya.\n\n4. Luar sebelum dalam. 月 dimulai dari bentuk pembungkusnya sebelum dua goresan mendatar di dalam. 同, 用, dan 周 mengikuti pola yang sama.\n\n5. Penutup kotak paling akhir. 国 ditulis tiga sisi kotaknya dulu, lalu semua isinya, baru garis bawah menutupnya. Menulis kotak penuh lebih dulu adalah kesalahan pemula yang paling sering terjadi.\n\n6. Tengah sebelum sayap pada karakter simetris. 小 dimulai dari kait tengah, lalu kiri, lalu kanan. 水 dan 承 berbentuk sama.\n\n7. Goresan jatuh-kiri sebelum jatuh-kanan. 人 dimulai dari goresan yang jatuh ke kiri baru ke kanan. Ini berlaku juga di dalam karakter yang lebih besar - 文, 交, 这.\n\n8. Titik dan goresan kecil paling akhir. Titik pada 玉 ditulis setelah 王 di bawahnya. Goresan kecil penutup biasanya mengakhiri karakter, bukan membukanya.\n\n## Kalau dua aturan bertabrakan\n\nAturan-aturan ini kadang bertabrakan, dan kalau begitu, atas-ke-bawah dan kiri-ke-kanan biasanya menang. 里 contoh yang bagus: 日 di atas ditulis lebih dulu sebagai satu kesatuan utuh, baru 土 di bawahnya - bukan menulis semua goresan mendatarnya sekaligus.\n\n## Cara tercepat menguasai urutan goresan\n\nCara tercepat menguasai ini adalah menulis karakternya sambil melihat urutannya, bukan menghafal daftarnya. Setiap karakter di situs ini punya animasi urutan goresan yang bisa diputar ulang, dan mode latihan yang memberitahu saat urutan atau arahnya salah - bagian yang tidak bisa dilakukan diagram diam."},demos:[{char:"三",pinyin:"sān",gloss:{en:"three",id:"tiga"},note:{en:"Rule 1, top to bottom. Three horizontals, written from the top down - the rule that overrides the others when they conflict.",id:"Aturan 1, atas ke bawah. Tiga goresan mendatar, ditulis dari atas - aturan yang mengalahkan yang lain saat bertabrakan."}},{char:"十",pinyin:"shí",gloss:{en:"ten",id:"sepuluh"},note:{en:"Rule 3, horizontal before vertical when strokes cross. Watch the horizontal go first, then the vertical through it.",id:"Aturan 3, mendatar sebelum tegak kalau bersilangan. Perhatikan goresan mendatar lebih dulu, baru yang tegak menembusnya."}},{char:"月",pinyin:"yuè",gloss:{en:"moon; month",id:"bulan"},note:{en:"Rule 4, outside before inside. The enclosing shape is drawn before the two horizontals land inside it.",id:"Aturan 4, luar sebelum dalam. Bentuk pembungkusnya digambar sebelum dua goresan mendatar masuk ke dalamnya."}},{char:"国",pinyin:"guó",gloss:{en:"country",id:"negara"},note:{en:"Rule 5, and the one beginners get wrong most. Three sides of the box, then everything inside, and only then the bottom line sealing it.",id:"Aturan 5, dan yang paling sering salah bagi pemula. Tiga sisi kotak, lalu semua isinya, baru garis bawah menutupnya."}},{char:"小",pinyin:"xiǎo",gloss:{en:"small",id:"kecil"},note:{en:"Rule 6, centre before wings. The central hook comes first, then left, then right.",id:"Aturan 6, tengah sebelum sayap. Kait tengah lebih dulu, lalu kiri, lalu kanan."}},{char:"里",pinyin:"lǐ",gloss:{en:"inside; li (unit)",id:"dalam; li (satuan)"},note:{en:"The conflict case from the article. 日 is completed as a unit first, then 土 beneath it - rather than writing all the horizontals together.",id:"Kasus tabrakan aturan dari artikel. 日 diselesaikan dulu sebagai satu kesatuan, baru 土 di bawahnya - bukan menulis semua goresan mendatarnya sekaligus."}}],related:[{href:"/char/%E5%A5%BD",label:{en:"Stroke order for 好",id:"Urutan goresan 好"}},{href:"/radicals",label:{en:"Radicals reference",id:"Referensi radikal"}},{href:"/hsk/1",label:{en:"HSK 1 vocabulary",id:"Kosakata HSK 1"}}]},{slug:"nada-mandarin",image:{src:"/brand/art/lanterns.webp",alt:{en:"Ink painting of red lanterns rising in mist",id:"Lukisan tinta lampion merah yang naik dalam kabut"}},sources:[{label:"Ujian HSK - situs resmi Chinese Testing International",url:"https://www.chinesetest.cn"},{label:"Daftar kosakata HSK (complete-hsk-vocabulary)",url:"https://github.com/drkameleon/complete-hsk-vocabulary"}],faq:[{q:{en:"How many tones does Mandarin have?",id:"Nada Mandarin ada berapa?"},a:{en:"Four tones plus a neutral tone. The first is high and flat, the second rises, the third dips then rises, the fourth falls sharply. The neutral tone is not a fifth tone but the absence of one, taking its pitch from what comes before it.",id:"Empat nada ditambah satu nada netral. Nada satu tinggi dan datar, nada dua naik, nada tiga turun lalu naik, nada empat turun tajam. Nada netral bukan nada kelima melainkan ketiadaan nada, dan tingginya mengikuti apa yang datang sebelumnya."}},{q:{en:"Why are Mandarin tones hard for Indonesian speakers?",id:"Kenapa nada Mandarin sulit bagi orang Indonesia?"},a:{en:"Indonesian is not a tonal language. Pitch in Indonesian carries emotion and emphasis, not word identity, so the instinct is to hear a Mandarin tone as a mood rather than as part of the word. That shift in how you listen is most of the work.",id:"Bahasa Indonesia tidak bernada. Tinggi-rendah suara dalam bahasa Indonesia membawa emosi dan penekanan, bukan identitas kata, jadi nalurinya mendengar nada Mandarin sebagai suasana hati. Pergeseran cara mendengar itu sudah sebagian besar pekerjaannya."}},{q:{en:"What is tone sandhi?",id:"Apa itu perubahan nada atau tone sandhi?"},a:{en:"A rule where tones change in combination. The one you meet first: when two third tones sit together, the first becomes a second tone. 你好 is written nǐ hǎo but said ní hǎo.",id:"Aturan di mana nada berubah saat digabung. Yang pertama kamu temui: kalau dua nada tiga bertemu, yang pertama berubah menjadi nada dua. 你好 ditulis nǐ hǎo tapi diucapkan ní hǎo."}},{q:{en:"How do I practise tones?",id:"Bagaimana cara melatih nada Mandarin?"},a:{en:"Practise tone pairs, not single tones. A tone in isolation is easy and almost never what you actually say; the difficulty lives in the transition between two of them. Listen and imitate out loud rather than reading a chart.",id:"Latih pasangan nada, bukan nada tunggal. Nada yang berdiri sendiri mudah dan hampir tidak pernah diucapkan begitu; kesulitannya ada di peralihan antara dua nada. Dengarkan dan tirukan dengan suara, bukan membaca tabel."}}],date:"2026-08-07",title:{en:"Mandarin tones: the 4 tones, the neutral one, and why they feel hard",id:"Nada Mandarin: 4 nada dan nada netral, dan kenapa terasa sulit"},description:{en:"Mandarin has four tones plus a neutral one. Indonesian is not tonal, which creates specific confusions - and knowing which ones makes them fixable.",id:"Nada Mandarin ada empat, plus nada netral. Bahasa Indonesia tidak bernada, dan itu menimbulkan kebingungan khas yang justru bisa diperbaiki."},body:{en:"Mandarin has four tones and a neutral one. That much is in every textbook. What textbooks written for English speakers do not address is why tones are hard for a specific listener, and the answer differs depending on the language you already speak.\n\nIndonesian is not tonal. Pitch in Indonesian does real work, but at the level of the sentence: it marks a question, or emphasis, or attitude. It never distinguishes one word from another. So the difficulty is not hearing pitch - Indonesian speakers hear pitch perfectly well - it is accepting that pitch belongs to the syllable rather than the sentence. 妈 (mā, mother) and 骂 (mà, to scold) are different words, not the same word said in two moods.\n\nThat single reframing is most of the work. The rest is knowing which pairs actually trip people up.\n\nSecond tone and third tone are the pair that causes the most trouble. Second tone rises. Third tone dips and then rises, and in ordinary speech the rise is often barely there - it mostly just sounds low. So they get confused in both directions: a third tone heard as a second, and a second produced as a third. If you drill one pair, drill this one.\n\nFirst tone is high and level, and it feels unnatural to hold a pitch steady across a whole syllable when your first language lets pitch drift. It tends to sag toward the end. Holding it flat is a physical habit more than a listening skill.\n\nFourth tone falls sharply and often sounds angry or abrupt to Indonesian ears, because a sharp falling pitch in Indonesian carries exactly that. It is worth knowing this explicitly, because learners often soften their fourth tone to avoid sounding rude - and a softened fourth tone stops being a fourth tone.\n\nThe neutral tone is not a fifth tone; it is the absence of one. It takes its height from what came before, which is why it cannot be practised in isolation and only makes sense inside a word: 妈妈 (māma), 谢谢 (xièxie).\n\nOne rule you will meet early: when two third tones sit next to each other, the first becomes a second tone. 你好 is written nǐ hǎo and said ní hǎo. This is not an exception to memorise so much as something your mouth does anyway once you have said it enough times.\n\nThe practical approach is to drill tone pairs rather than single tones. A tone in isolation is easy; a tone next to another tone is where the real difficulty lives, and it is what actual speech consists of.",id:"Mandarin punya empat nada plus satu nada netral. Itu ada di semua buku pelajaran. Yang tidak dibahas buku yang ditulis untuk penutur bahasa Inggris adalah kenapa nada terasa sulit bagi pendengar tertentu - dan jawabannya berbeda tergantung bahasa yang sudah kamu kuasai.\n\n## Kenapa nada Mandarin sulit bagi orang Indonesia\n\nBahasa Indonesia tidak bernada. Tinggi-rendah suara dalam bahasa Indonesia tetap bekerja, tapi di tingkat kalimat: menandai pertanyaan, penekanan, atau sikap. Ia tidak pernah membedakan satu kata dari kata lain. Jadi kesulitannya bukan mendengar nada - penutur Indonesia mendengar nada dengan baik - melainkan menerima bahwa nada itu milik suku kata, bukan milik kalimat. 妈 (mā, ibu) dan 骂 (mà, memarahi) adalah dua kata berbeda, bukan satu kata yang diucapkan dengan dua suasana hati.\n\nPergeseran cara pandang itu saja sudah sebagian besar pekerjaannya. Sisanya adalah tahu pasangan mana yang benar-benar sering tertukar.\n\n## Nada 2 dan nada 3: pasangan paling merepotkan\n\nNada dua dan nada tiga adalah pasangan yang paling merepotkan. Nada dua naik. Nada tiga turun lalu naik, dan dalam percakapan biasa naiknya sering nyaris tidak terdengar - kebanyakan hanya terdengar rendah. Jadi keduanya tertukar dua arah: nada tiga terdengar seperti nada dua, dan nada dua diucapkan seperti nada tiga. Kalau kamu hanya sempat melatih satu pasangan, latih yang ini.\n\n## Nada 1 dan nada 4\n\nNada satu tinggi dan datar, dan menahan nada tetap rata sepanjang satu suku kata terasa tidak alami kalau bahasa pertamamu membiarkan nada bergeser. Nada satu cenderung melorot di ujung. Menahannya tetap datar lebih merupakan kebiasaan fisik daripada kemampuan mendengar.\n\nNada empat turun tajam dan sering terdengar marah atau ketus di telinga orang Indonesia, karena nada turun tajam dalam bahasa Indonesia memang membawa kesan itu. Ini perlu disadari secara eksplisit, karena pelajar sering melembutkan nada empat supaya tidak terdengar kasar - dan nada empat yang dilembutkan berhenti menjadi nada empat.\n\n## Nada netral: bukan nada kelima\n\nNada netral bukan nada kelima; ia justru ketiadaan nada. Tingginya mengikuti apa yang datang sebelumnya, sehingga tidak bisa dilatih sendirian dan baru masuk akal di dalam kata: 妈妈 (māma), 谢谢 (xièxie).\n\n## Perubahan nada (tone sandhi)\n\nSatu aturan yang akan kamu temui sejak awal: kalau dua nada tiga bertemu, yang pertama berubah menjadi nada dua. 你好 ditulis nǐ hǎo tapi diucapkan ní hǎo. Ini bukan pengecualian yang perlu dihafal, melainkan sesuatu yang mulutmu lakukan sendiri setelah cukup sering mengucapkannya.\n\n## Cara melatih nada Mandarin\n\nCara paling praktis adalah melatih pasangan nada, bukan nada tunggal. Nada yang berdiri sendiri itu mudah; kesulitan sebenarnya muncul saat satu nada bertemu nada lain - dan percakapan nyata justru terdiri dari itu."},demos:[{char:"妈",pinyin:"mā",gloss:{en:"mother",id:"ibu"},note:{en:"First tone: high and level. Play it, then play 骂 below - same syllable, different word.",id:"Nada satu: tinggi dan datar. Putar ini, lalu putar 骂 di bawah - suku kata sama, kata berbeda."}},{char:"骂",pinyin:"mà",gloss:{en:"to scold",id:"memarahi"},note:{en:"Fourth tone: falls sharply. To an Indonesian ear this can sound angry, because a sharp fall carries that in Indonesian. Softening it stops it being a fourth tone.",id:"Nada empat: turun tajam. Di telinga orang Indonesia bisa terdengar marah, karena penurunan tajam memang membawa kesan itu. Melembutkannya membuatnya berhenti jadi nada empat."}},{char:"好",pinyin:"hǎo",gloss:{en:"good",id:"baik"},note:{en:"Third tone: dips, then rises - and in ordinary speech the rise is barely there. This is the one confused with second tone in both directions.",id:"Nada tiga: turun lalu naik - dan dalam percakapan biasa naiknya nyaris tidak terdengar. Inilah yang tertukar dengan nada dua, dua arah."}}],related:[{href:"/tones",label:{en:"Tone trainer",id:"Latihan nada"}},{href:"/pinyin",label:{en:"Pinyin guide",id:"Panduan pinyin"}},{href:"/hsk/1",label:{en:"HSK 1 vocabulary",id:"Kosakata HSK 1"}}]},{slug:"belajar-mandarin-dari-nol",image:{src:"/brand/art/desk.webp",alt:{en:"Ink painting of a study desk with brush, paper and an open book",id:"Lukisan tinta meja belajar dengan kuas, kertas, dan buku terbuka"}},sources:[{label:"Ujian HSK - situs resmi Chinese Testing International",url:"https://www.chinesetest.cn"},{label:"Daftar kosakata HSK (complete-hsk-vocabulary)",url:"https://github.com/drkameleon/complete-hsk-vocabulary"}],faq:[{q:{en:"How long does it take to learn Mandarin?",id:"Berapa lama belajar bahasa Mandarin sampai bisa?"},a:{en:"With 30 to 60 minutes a day, consistently: basic conversation in 3 to 6 months, HSK 3 in 6 to 10 months, and HSK 4, the usual scholarship requirement, in 12 to 18 months. Daily consistency matters far more than session length.",id:"Dengan 30 sampai 60 menit sehari secara konsisten: percakapan dasar dalam 3 sampai 6 bulan, HSK 3 dalam 6 sampai 10 bulan, dan HSK 4 yang jadi syarat umum beasiswa dalam 12 sampai 18 bulan. Konsistensi harian jauh lebih menentukan daripada durasi tiap sesi."}},{q:{en:"What should I learn first?",id:"Apa yang harus dipelajari paling pertama?"},a:{en:"Pronunciation, and only pronunciation, for the first week: pinyin and the four tones. Everything after is built on it, and a wrong foundation means every word you memorise afterwards is slightly wrong too.",id:"Pelafalan, dan hanya pelafalan, di minggu pertama: pinyin dan empat nada. Semua setelahnya dibangun di atasnya, dan fondasi yang salah membuat setiap kata yang kamu hafal ikut miring."}},{q:{en:"Can I learn Mandarin on my own?",id:"Apakah bisa belajar Mandarin otodidak?"},a:{en:"Most of it, yes. Memorising vocabulary, characters and tones is actually more effective alone with scheduled repetition. What is hard alone is conversation and pronunciation correction, and that is where a teacher or practice partner earns their cost.",id:"Sebagian besarnya bisa. Menghafal kosakata, karakter, dan nada justru lebih efektif dilakukan sendiri dengan pengulangan terjadwal. Yang sulit otodidak adalah percakapan dan koreksi lafal, dan di situlah guru atau teman latihan sepadan dengan biayanya."}},{q:{en:"How many words do I need to start speaking?",id:"Berapa kata yang perlu dihafal untuk mulai bicara?"},a:{en:"About fifty, chosen for usefulness rather than frequency, will carry a first conversation. The HSK 1 list of roughly 150 covers most everyday situations a beginner meets.",id:"Sekitar lima puluh kata, dipilih berdasarkan kegunaan dan bukan frekuensi, sudah cukup untuk percakapan pertama. Daftar HSK 1 yang sekitar 150 kata menutup sebagian besar situasi sehari-hari yang ditemui pemula."}}],date:"2026-08-08",title:{en:"Learning Mandarin from zero: what to do in the first month",id:"Belajar Bahasa Mandarin dari Nol: Panduan Bulan Pertama"},description:{en:"A concrete order for the first month of Mandarin - pinyin, tones, the first characters - and the two things beginners waste time on.",id:"Urutan konkret untuk bulan pertama belajar Mandarin - pinyin, nada, karakter pertama - dan dua hal yang membuang waktu pemula."},body:{en:"Most people who start Mandarin and stop did not find it too hard. They found it shapeless. There is no obvious first thing, the advice online contradicts itself, and after three weeks of collecting apps and PDFs there is nothing to show. What follows is an order, not a syllabus - the point is that you always know what the next thing is.\n\nWeek one is pronunciation, and only pronunciation. Learn pinyin properly: what the letters mean, which ones lie to you (c is 'ts', q is close to 'ch', x is close to 'sh'), and the four tones plus the neutral one. This feels like a detour because you are not learning any words. It is not. Pinyin is the notation everything else is written in, and a wrong pronunciation learned now gets rehearsed into permanence over the following year. A week here saves months later.\n\nWeek two is your first fifty words, chosen for use rather than for frequency lists. Greetings, numbers, the words for yes-ish and no-ish, please, thank you, sorry, how much, I want, I don't understand. Say every one out loud. If you cannot say a word, you do not know it - recognising it on a screen is a different skill and a weaker one.\n\nWeek three is where characters start, and where most beginners go wrong in one of two directions. Some refuse characters entirely and stay on pinyin, which works for about two months and then collapses, because pinyin is ambiguous and real Chinese is not written in it. Others try to learn characters as pictures, memorising each one whole, which does not scale past a few hundred. The way through is components: characters are built from a small set of repeating parts, and once you can see 女, 口, 木, 氵 inside larger characters, you are learning combinations rather than pictures. Start writing them by hand from day one - stroke order included, because that is what turns a character from a picture into a sequence you can reproduce.\n\nWeek four is your first real sentences, and the good news is that Mandarin grammar is genuinely simpler than Indonesian or English here. No verb conjugation. No tenses in the European sense. No plurals, no articles, no gender. Word order does the work, and the basic order - subject, verb, object - is the one you already use. 我要这个 is literally I-want-this.\n\nTwo things to avoid, both of which feel productive. The first is collecting resources: another app, another PDF, another YouTube channel. Choosing takes the time that learning was supposed to. Pick one thing and finish a week of it. The second is passive input too early - films and songs with subtitles feel like study and are close to useless below roughly 500 words, because you cannot notice what you have no representation for.\n\nAfter the first month the shape changes: you stop learning about Mandarin and start accumulating it, and the thing that matters most becomes review rather than new material. That is the point where a spaced repetition system earns its place, because the enemy is no longer difficulty, it is forgetting.",id:"Kebanyakan orang yang mulai belajar Mandarin lalu berhenti bukan karena merasa terlalu sulit. Mereka merasa tidak ada bentuknya. Tidak jelas apa yang harus dipelajari pertama, saran di internet saling bertentangan, dan setelah tiga minggu mengumpulkan aplikasi dan PDF tidak ada hasil yang bisa ditunjukkan. Yang di bawah ini adalah urutan, bukan silabus - intinya kamu selalu tahu apa langkah berikutnya.\n\n## Minggu 1: pelafalan saja\n\nMinggu pertama untuk pelafalan, dan hanya pelafalan. Pelajari pinyin dengan benar: apa arti hurufnya, mana yang menipu (c dibaca 'ts', q dekat ke 'ch', x dekat ke 'sh'), dan empat nada plus nada netral. Ini terasa seperti memutar jalan karena kamu belum belajar kata apa pun. Sebenarnya tidak. Pinyin adalah notasi tempat semua hal lain ditulis, dan pelafalan salah yang dipelajari sekarang akan dilatih terus sampai menetap sepanjang tahun berikutnya. Satu minggu di sini menghemat berbulan-bulan nanti.\n\n## Minggu 2: lima puluh kata pertama\n\nMinggu kedua untuk lima puluh kata pertama, dipilih berdasarkan kegunaan, bukan daftar frekuensi. Sapaan, angka, kata untuk iya dan tidak, tolong, terima kasih, maaf, berapa harganya, saya mau, saya tidak mengerti. Ucapkan semuanya keras-keras. Kalau kamu tidak bisa mengucapkan sebuah kata, kamu belum menguasainya - mengenalinya di layar adalah keterampilan lain yang lebih lemah.\n\n## Minggu 3: mulai karakter\n\nMinggu ketiga waktunya mulai karakter, dan di sinilah kebanyakan pemula salah arah, ke salah satu dari dua sisi. Sebagian menolak karakter sama sekali dan bertahan di pinyin - cara ini bertahan sekitar dua bulan lalu runtuh, karena pinyin ambigu dan bahasa Mandarin sungguhan tidak ditulis dengan pinyin. Sebagian lain mencoba menghafal karakter sebagai gambar utuh, dan itu tidak sanggup melewati beberapa ratus karakter. Jalan keluarnya adalah komponen: karakter dibangun dari sekumpulan kecil bagian yang berulang, dan begitu kamu bisa melihat 女, 口, 木, 氵 di dalam karakter yang lebih besar, kamu sedang mempelajari kombinasi, bukan gambar. Mulai menulisnya dengan tangan sejak hari pertama - termasuk urutan goresannya, karena itulah yang mengubah karakter dari gambar menjadi rangkaian yang bisa kamu hasilkan ulang.\n\n## Minggu 4: kalimat pertama\n\nMinggu keempat untuk kalimat pertama yang sesungguhnya, dan kabar baiknya tata bahasa Mandarin di titik ini memang lebih sederhana daripada bahasa Indonesia atau Inggris. Tidak ada konjugasi kata kerja. Tidak ada kala seperti di bahasa Eropa. Tidak ada bentuk jamak, tidak ada kata sandang, tidak ada gender. Urutan kata yang bekerja, dan urutan dasarnya - subjek, kata kerja, objek - sudah kamu pakai sehari-hari. 我要这个 secara harfiah berarti saya-mau-ini.\n\n## Dua hal yang terasa produktif tapi membuang waktu\n\nDua hal yang perlu dihindari, dan keduanya terasa produktif. Pertama, mengumpulkan sumber belajar: satu aplikasi lagi, satu PDF lagi, satu kanal YouTube lagi. Waktu untuk memilih memakan waktu yang seharusnya dipakai belajar. Pilih satu, lalu selesaikan satu minggu dengannya. Kedua, terlalu cepat masuk ke input pasif - film dan lagu dengan subtitel terasa seperti belajar tapi nyaris tidak berguna di bawah sekitar 500 kata, karena kamu tidak bisa memperhatikan sesuatu yang belum punya wakil di kepalamu.\n\n## Setelah bulan pertama\n\nSetelah bulan pertama, bentuknya berubah: kamu berhenti belajar tentang bahasa Mandarin dan mulai menumpuknya, dan yang paling menentukan bukan lagi materi baru melainkan pengulangan. Di titik itulah sistem pengulangan berjarak mulai berguna, karena musuhnya bukan lagi kesulitan, melainkan lupa."},demos:[{char:"你好",pinyin:"nǐ hǎo",gloss:{en:"hello",id:"halo"},note:{en:"Week two, word one. Two third tones in a row, so the first shifts to a second tone - said ní hǎo, not nǐ hǎo.",id:"Minggu kedua, kata pertama. Dua nada tiga berturut-turut, jadi yang pertama berubah jadi nada dua - dibaca ní hǎo, bukan nǐ hǎo."}},{char:"谢谢",pinyin:"xiè xie",gloss:{en:"thank you",id:"terima kasih"},note:{en:"The second syllable is neutral - no tone of its own, it just takes its height from the first. This is why the neutral tone cannot be practised alone.",id:"Suku kata kedua netral - tidak punya nada sendiri, tingginya mengikuti yang pertama. Karena itu nada netral tidak bisa dilatih sendirian."}},{char:"多少钱",pinyin:"duō shao qián",gloss:{en:"how much (money)?",id:"berapa harganya?"},note:{en:"Three syllables, three different tone behaviours - and one of the few phrases you will use on your first day in a shop.",id:"Tiga suku kata, tiga perilaku nada berbeda - dan salah satu frasa yang langsung terpakai di hari pertama kamu masuk toko."}},{char:"对不起",pinyin:"duì bu qǐ",gloss:{en:"sorry",id:"maaf"},note:{en:"Falling, neutral, then third. Worth learning as one sound rather than three, which is how it is actually said.",id:"Turun, netral, lalu nada tiga. Lebih baik dihafal sebagai satu bunyi daripada tiga, karena begitulah cara mengucapkannya."}}],related:[{href:"/pinyin",label:{en:"Pinyin guide",id:"Panduan pinyin"}},{href:"/blog/nada-mandarin",label:{en:"Mandarin tones explained",id:"Nada Mandarin dijelaskan"}},{href:"/course/1",label:{en:"Start Lesson 1",id:"Mulai Pelajaran 1"}}]},{slug:"kosakata-mandarin-sehari-hari",image:{src:"/brand/art/street.webp",alt:{en:"Ink painting of a misty street of tea houses and hanging lanterns",id:"Lukisan tinta jalanan berkabut dengan kedai teh dan lampion gantung"}},sources:[{label:"Daftar kosakata HSK (complete-hsk-vocabulary)",url:"https://github.com/drkameleon/complete-hsk-vocabulary"},{label:"Ujian HSK - situs resmi Chinese Testing International",url:"https://www.chinesetest.cn"}],faq:[{q:{en:"Which Mandarin words should I learn first?",id:"Kosakata Mandarin apa yang paling penting dipelajari dulu?"},a:{en:"Not the ones on frequency lists. The most frequent words are grammatical particles, useless until you can build a sentence. Learn the words for four situations instead: greeting and closing, buying something, stating what you want, and admitting you did not understand.",id:"Bukan yang ada di daftar frekuensi. Kata yang paling sering muncul adalah partikel tata bahasa, tidak berguna sampai kamu bisa menyusun kalimat. Pelajari kata untuk empat situasi ini: menyapa dan menutup, membeli sesuatu, menyatakan keinginan, dan mengakui kamu tidak paham."}},{q:{en:"How many words do I need for basic conversation?",id:"Berapa kosakata yang perlu dihafal untuk percakapan dasar?"},a:{en:"Around 150, the HSK 1 list, covers most everyday exchanges. Roughly fifty well-chosen words already carry a first conversation with a patient listener.",id:"Sekitar 150 kata, yaitu daftar HSK 1, menutup sebagian besar percakapan sehari-hari. Sekitar lima puluh kata yang dipilih dengan baik sudah cukup untuk percakapan pertama dengan lawan bicara yang sabar."}},{q:{en:"How should I memorise vocabulary?",id:"Bagaimana cara menghafal kosakata Mandarin?"},a:{en:"Out loud, inside a whole phrase, with scheduled repetition. A word learned as a bare item on a list does not surface when you need it; a word learned inside a sentence you have said aloud does.",id:"Dengan suara, di dalam frasa utuh, dan dengan pengulangan terjadwal. Kata yang dihafal sebagai butir kosong di daftar tidak muncul saat dibutuhkan; kata yang dipelajari di dalam kalimat yang pernah kamu ucapkan akan muncul."}}],date:"2026-08-08",title:{en:"Everyday Mandarin vocabulary: the words you use before you can hold a conversation",id:"Kosakata Mandarin Sehari-hari: 4 Situasi Paling Terpakai"},description:{en:"The everyday Mandarin words that do the most work - ordering, paying, asking, apologising - with pronunciation you can play.",id:"Kosakata Mandarin sehari-hari yang paling banyak terpakai - memesan, membayar, bertanya, meminta maaf - lengkap dengan pelafalan."},body:{en:"Frequency lists are the usual way to pick a first vocabulary, and they are misleading. The most frequent words in Chinese are grammatical particles - 的, 了, 是 - which are essential to understanding a sentence and useless for producing one on your first day. What you need first is not the most common vocabulary but the most load-bearing: the words that let you complete an interaction rather than describe one.\n\nThere are roughly four situations that account for most early real-world Mandarin, and they are worth learning as situations rather than as a list.\n\nGetting someone's attention and closing the exchange. 你好 to open, 请问 before a question to a stranger, 谢谢 and 不客气 to close, 对不起 and 没关系 when something goes wrong, 再见 to leave. These are formulaic - they never change form - which means each one is a complete tool the moment you learn it. That is unusual in language learning and worth exploiting early.\n\nBuying things. 多少钱 is the single highest-return phrase in the language for a traveller, and 买单 gets you the bill in a restaurant. Numbers matter more than they look: prices are said quickly and you will understand nothing if the numbers are not automatic, so drill one to a hundred until they need no thought.\n\nSaying what you want. 我要 plus a noun covers an enormous amount of ordering and asking - I want this, I want that. Pointing plus 这个 is not a failure of language, it is what everyone does, including native speakers in a noisy shop.\n\nAdmitting you are lost. 我听不懂 (I don't understand), 请说慢一点 (please speak more slowly), 可以 and 不用 for yes-ish and no-ish. Learners often skip these because they feel like an admission of weakness. They are the opposite: they are what lets a conversation continue instead of ending, and every hour you spend in a continuing conversation is worth more than an hour of study.\n\nThe useful discipline with everyday vocabulary is to learn it out loud and in context, never as a column of words with meanings beside them. A word you have only read is a word you will not produce under pressure - and everyday vocabulary exists entirely to be produced under pressure.",id:"Daftar frekuensi biasanya dipakai untuk memilih kosakata pertama, dan itu menyesatkan. Kata paling sering muncul dalam bahasa Mandarin adalah partikel tata bahasa - 的, 了, 是 - yang penting untuk memahami kalimat tapi tidak berguna untuk menyusun kalimat di hari pertamamu. Yang kamu butuhkan pertama bukan kosakata paling umum, melainkan yang paling menanggung beban: kata yang membuatmu bisa menyelesaikan sebuah interaksi, bukan menggambarkannya.\n\n## Empat situasi yang mencakup sebagian besar percakapan\n\nAda kira-kira empat situasi yang mencakup sebagian besar pemakaian Mandarin nyata di tahap awal, dan lebih baik dipelajari sebagai situasi daripada sebagai daftar.\n\n## 1. Menyapa dan menutup percakapan\n\nMenarik perhatian orang dan menutup percakapan. 你好 untuk membuka, 请问 sebelum bertanya kepada orang asing, 谢谢 dan 不客气 untuk menutup, 对不起 dan 没关系 saat ada yang keliru, 再见 saat pamit. Semua ini bersifat formulaik - bentuknya tidak pernah berubah - yang berarti tiap satu langsung menjadi alat utuh begitu kamu menghafalnya. Itu hal yang jarang dalam belajar bahasa dan layak dimanfaatkan sejak awal.\n\n## 2. Membeli dan menanyakan harga\n\nMembeli sesuatu. 多少钱 adalah frasa dengan imbal hasil tertinggi bagi pelancong, dan 买单 membuatmu mendapat tagihan di restoran. Angka lebih penting daripada kelihatannya: harga diucapkan cepat dan kamu tidak akan menangkap apa pun kalau angkanya belum otomatis, jadi latih satu sampai seratus sampai tidak perlu berpikir.\n\n## 3. Menyatakan keinginan dan memesan\n\nMenyatakan keinginan. 我要 ditambah kata benda sudah mencakup sangat banyak keperluan memesan dan meminta - saya mau ini, saya mau itu. Menunjuk sambil bilang 这个 bukan kegagalan berbahasa; itu yang dilakukan semua orang, termasuk penutur asli di toko yang berisik.\n\n## 4. Saat kamu tidak paham\n\nMengakui kamu tidak paham. 我听不懂 (saya tidak mengerti), 请说慢一点 (tolong bicara lebih pelan), 可以 dan 不用 untuk iya dan tidak. Pelajar sering melewati kelompok ini karena terasa seperti mengakui kelemahan. Justru sebaliknya: inilah yang membuat percakapan berlanjut alih-alih berhenti, dan satu jam di dalam percakapan yang berlanjut lebih berharga daripada satu jam belajar sendiri.\n\n## Cara menghafalnya supaya benar-benar terpakai\n\nDisiplin yang berguna untuk kosakata sehari-hari adalah mempelajarinya dengan suara dan dalam konteks, tidak pernah sebagai kolom kata dengan artinya di sebelahnya. Kata yang hanya pernah kamu baca adalah kata yang tidak akan keluar saat kamu tertekan - dan kosakata sehari-hari justru ada untuk dipakai dalam keadaan tertekan."},demos:[{char:"请",pinyin:"qǐng",gloss:{en:"please; to invite",id:"tolong; mempersilakan"},note:{en:"q is not the English q - it is close to 'ch' with the tongue further forward. Getting this one wrong early is a habit that lasts.",id:"q bukan seperti q dalam bahasa Inggris - bunyinya dekat ke 'ch' dengan lidah lebih ke depan. Salah di sini sejak awal jadi kebiasaan yang bertahan lama."}},{char:"多少钱",pinyin:"duō shao qián",gloss:{en:"how much (money)?",id:"berapa harganya?"},note:{en:"The highest-return phrase in this list. Learn the answer numbers alongside it or you will ask a question you cannot understand the answer to.",id:"Frasa dengan imbal hasil tertinggi di daftar ini. Hafalkan angkanya sekalian, atau kamu bertanya tapi tidak paham jawabannya."}},{char:"买单",pinyin:"mǎi dān",gloss:{en:"the bill, please",id:"minta bill"},note:{en:"Two words that end a restaurant meal. Third tone then first - and the third tone here is a full dip, because it stands before a first tone.",id:"Dua kata yang menutup makan di restoran. Nada tiga lalu nada satu - dan nada tiganya penuh, karena berdiri sebelum nada satu."}},{char:"不客气",pinyin:"bú kè qi",gloss:{en:"you're welcome",id:"sama-sama"},note:{en:"不 is normally fourth tone but shifts to second before another fourth tone - bú, not bù. One of the two tone-change rules worth knowing early.",id:"不 biasanya nada empat tapi berubah jadi nada dua di depan nada empat lain - bú, bukan bù. Salah satu dari dua aturan perubahan nada yang perlu diketahui sejak awal."}},{char:"可以",pinyin:"kě yǐ",gloss:{en:"can; may; OK",id:"boleh; bisa"},note:{en:"Two third tones, so the first becomes a second: ké yǐ. Also the most useful single word for agreeing to anything.",id:"Dua nada tiga, jadi yang pertama berubah jadi nada dua: ké yǐ. Sekaligus kata tunggal paling berguna untuk menyetujui apa pun."}}],related:[{href:"/themes/daily",label:{en:"Everyday vocabulary pack",id:"Paket kosakata sehari-hari"}},{href:"/hsk/1",label:{en:"HSK 1 vocabulary",id:"Kosakata HSK 1"}},{href:"/blog/belajar-mandarin-dari-nol",label:{en:"Learning Mandarin from zero",id:"Belajar Mandarin dari nol"}}]},{slug:"angka-mandarin",image:{src:"/brand/art/hero-path.webp",alt:{en:"Ink painting of a mountain path receding into mist",id:"Lukisan tinta jalan setapak pegunungan yang memudar dalam kabut"}},sources:[{label:"Daftar kosakata HSK (complete-hsk-vocabulary)",url:"https://github.com/drkameleon/complete-hsk-vocabulary"},{label:"Ujian HSK - situs resmi Chinese Testing International",url:"https://www.chinesetest.cn"}],faq:[{q:{en:"How do you write Mandarin numbers 1 to 10?",id:"Bagaimana cara menulis angka Mandarin 1 sampai 10?"},a:{en:"The ten characters are the numerals one through ten. The first three are literally one, two and three horizontal strokes. Learn these ten out loud before anything else, because every number to 99 is built from them and nothing more.",id:"Sepuluh karakternya: 一 二 三 四 五 六 七 八 九 十. Tiga yang pertama benar-benar satu, dua, dan tiga garis mendatar. Kuasai sepuluh ini dengan suara sebelum lanjut, karena semua angka sampai 99 dibangun dari itu saja."}},{q:{en:"Why does 二 change to 两?",id:"Kenapa 二 berubah menjadi 两?"},a:{en:"二 is two when counting or reading digits aloud. 两 is used before a measure word, when you mean two of something. So 二十 for twenty, but 两个 for two items, never 二个.",id:"二 adalah angka dua saat menghitung atau membaca deret angka. 两 dipakai di depan kata bantu bilangan, saat maksudmu dua buah sesuatu. Jadi 二十 untuk dua puluh, tapi 两个 untuk dua buah, tidak pernah 二个."}},{q:{en:"Why is 万 confusing for Indonesian speakers?",id:"Kenapa 万 membingungkan bagi penutur bahasa Indonesia?"},a:{en:"Because Chinese groups large numbers in units of ten thousand rather than thousand. 一万 is ten thousand, and a hundred thousand is 十万, literally ten of them, where Indonesian switches to a new word. Fluent speakers still hesitate converting large numbers, and it has nothing to do with arithmetic.",id:"Karena bahasa Mandarin mengelompokkan angka besar dalam satuan sepuluh ribu, bukan ribuan. 一万 adalah sepuluh ribu, dan seratus ribu adalah 十万, harfiahnya sepuluh kali itu, sementara bahasa Indonesia pindah ke kata baru. Penutur fasih pun masih ragu mengonversi angka besar, dan itu bukan soal berhitung."}},{q:{en:"Why can I recite numbers but not catch prices?",id:"Kenapa saya bisa menyebut angka tapi tidak menangkap harga?"},a:{en:"Recognising a number spoken quickly is a different skill from reciting it. Numbers need to be automatic rather than merely known, and that comes from hearing them repeatedly, not from understanding the pattern, which you already do.",id:"Mengenali 三十五 yang diucapkan cepat adalah keterampilan berbeda dari melafalkannya sendiri. Angka harus otomatis, bukan sekadar dipahami, dan itu datang dari sering mendengarnya, bukan dari memahami polanya yang sudah kamu kuasai."}}],date:"2026-08-08",title:{en:"Mandarin numbers 1–100: the whole system in ten characters",id:"Angka Mandarin 1–100: seluruh sistemnya cuma sepuluh karakter"},description:{en:"Mandarin numbers are the most regular part of the language. Learn ten characters and you can say every number to 99 - with pronunciation you can play.",id:"Angka Mandarin adalah bagian paling teratur dari bahasanya. Kuasai sepuluh karakter dan kamu bisa menyebut semua angka sampai 99, lengkap dengan pelafalan."},body:{en:"Mandarin numbers are the single best return on effort in the language. Ten characters get you every number to 99, the rule for combining them has no exceptions, and unlike almost everything else you will meet, there is nothing to memorise past the pattern.\n\n## Mandarin numbers 1 to 10\n\nStart with one to ten: 一 二 三 四 五 六 七 八 九 十. The first three are as simple as writing gets - one, two and three horizontal lines. Learn these ten properly, out loud, before going further, because everything below is built from them and nothing else.\n\n## 11 to 19: just add 十\n\nEleven to nineteen is 十 followed by the digit. 十一 is ten-one, eleven. 十五 is ten-five, fifteen. 十九 is nineteen. There is no separate word for eleven the way English has one, and no irregularity like 'twelve' or 'thirteen'.\n\n## 20 to 99: the same pattern, no exceptions\n\nTwenty to ninety-nine is the digit, then 十, then the remainder. 二十 is two-ten, twenty. 二十五 is two-ten-five, twenty-five. 九十九 is nine-ten-nine, ninety-nine. Say it as you read it and you have it: every number from 11 to 99 follows this without a single exception.\n\n## Hundreds, thousands, and 万 (ten thousand)\n\nOne hundred is 一百, and from there 千 is a thousand and 万 is ten thousand. That last one is the first genuine difference from English and worth pausing on: Chinese groups large numbers in units of ten thousand rather than thousand. 一万 is ten thousand, and a hundred thousand is 十万 - ten of them - where English switches to a new word. This is why fluent speakers still hesitate converting large numbers between the two languages, and it is nothing to do with arithmetic.\n\n## Two traps: 零 (zero) and 两\n\nTwo details that will otherwise trip you. 零 is zero, and appears inside numbers with a gap - 一百零五 is one-hundred-zero-five, 105. And 二 becomes 两 before a measure word: you say 二十 for twenty, but 两个 for two of something, never 二个.\n\n## Why prices are still hard to catch\n\nA warning worth taking seriously: prices are said fast. You will ask 多少钱 confidently and then understand nothing, because recognising 三十五 in the wild is a different skill from reciting it. Numbers need to be automatic rather than merely known, and that is a matter of hearing them repeatedly, not of understanding the pattern - which you already do, having read this far.",id:"Angka Mandarin adalah bagian dengan imbal hasil terbaik dalam bahasa ini. Sepuluh karakter sudah cukup untuk semua angka sampai 99, aturan penggabungannya tanpa pengecualian, dan tidak seperti hampir semua hal lain yang akan kamu temui, tidak ada yang perlu dihafal selain polanya.\n\n## Angka Mandarin 1 sampai 10\n\nMulai dari satu sampai sepuluh: 一 二 三 四 五 六 七 八 九 十. Tiga yang pertama sesederhana yang bisa dibayangkan - satu, dua, dan tiga garis mendatar. Kuasai sepuluh ini dengan benar dan dengan suara sebelum lanjut, karena semua di bawah dibangun dari itu saja.\n\n## Angka 11–19: cukup tambahkan 十\n\nSebelas sampai sembilan belas adalah 十 diikuti angkanya. 十一 berarti sepuluh-satu, sebelas. 十五 sepuluh-lima, lima belas. 十九 sembilan belas. Tidak ada kata khusus untuk sebelas seperti dalam bahasa Inggris, dan tidak ada bentuk tak beraturan seperti 'twelve' atau 'thirteen'.\n\n## Angka 20–99: pola yang sama persis\n\nDua puluh sampai sembilan puluh sembilan adalah angka, lalu 十, lalu sisanya. 二十 berarti dua-sepuluh, dua puluh. 二十五 dua-sepuluh-lima, dua puluh lima. 九十九 sembilan-sepuluh-sembilan, sembilan puluh sembilan. Baca apa adanya dan kamu sudah bisa: semua angka dari 11 sampai 99 mengikuti pola ini tanpa satu pun pengecualian.\n\n## Ratusan, ribuan, dan 万 (sepuluh ribu)\n\nSeratus adalah 一百, lalu 千 seribu dan 万 sepuluh ribu. Yang terakhir ini perbedaan sungguhan pertama dari bahasa Indonesia dan layak diperhatikan: bahasa Mandarin mengelompokkan angka besar dalam satuan sepuluh ribu, bukan ribuan. 一万 adalah sepuluh ribu, dan seratus ribu adalah 十万 - sepuluh kali itu. Inilah alasan penutur fasih pun masih ragu saat mengonversi angka besar antar bahasa, dan itu sama sekali bukan soal berhitung.\n\n## Dua jebakan: 零 (nol) dan 两\n\nDua hal kecil yang kalau tidak tahu akan membuatmu tersandung. 零 adalah nol, dan muncul di dalam angka yang ada 'lompatan' - 一百零五 berarti seratus-nol-lima, 105. Dan 二 berubah jadi 两 di depan kata bantu bilangan: kamu bilang 二十 untuk dua puluh, tapi 两个 untuk dua buah, tidak pernah 二个.\n\n## Kenapa angka sulit ditangkap saat mendengar harga\n\nSatu peringatan yang perlu diambil serius: harga diucapkan cepat. Kamu akan bertanya 多少钱 dengan percaya diri lalu tidak menangkap apa pun, karena mengenali 三十五 di dunia nyata adalah keterampilan yang berbeda dari melafalkannya sendiri. Angka harus otomatis, bukan sekadar dipahami - dan itu urusan sering mendengarnya, bukan memahami polanya, yang sudah kamu kuasai sejak membaca sampai sini."},demos:[{char:"一",pinyin:"yī",gloss:{en:"one",id:"satu"},note:{en:"One stroke, left to right. Also the character whose tone changes most: yī alone, but yì or yí depending on what follows.",id:"Satu goresan, kiri ke kanan. Sekaligus karakter yang nadanya paling sering berubah: yī kalau sendiri, tapi yì atau yí tergantung kata setelahnya."}},{char:"十",pinyin:"shí",gloss:{en:"ten",id:"sepuluh"},note:{en:"The pivot of the whole system. Horizontal first, then vertical - rule 3 from the stroke-order post.",id:"Poros seluruh sistemnya. Mendatar dulu, baru tegak - aturan 3 dari artikel urutan goresan."}},{char:"百",pinyin:"bǎi",gloss:{en:"hundred",id:"ratus"},note:{en:"一百 is one hundred. The 一 is not optional here, unlike English where 'hundred' can stand alone.",id:"一百 berarti seratus. 一-nya tidak opsional di sini, berbeda dengan bahasa Indonesia yang bisa bilang 'ratusan' saja."}},{char:"万",pinyin:"wàn",gloss:{en:"ten thousand",id:"sepuluh ribu"},note:{en:"The character that breaks the mapping to English. Chinese counts large numbers in units of 万, so 100,000 is 十万 - ten of these.",id:"Karakter yang memutus pemetaan ke bahasa Indonesia. Mandarin menghitung angka besar dalam satuan 万, jadi 100.000 adalah 十万 - sepuluh kali ini."}},{char:"零",pinyin:"líng",gloss:{en:"zero",id:"nol"},note:{en:"Used inside numbers with a gap: 一百零五 is 105. Far more strokes than every other number, and worth watching draw.",id:"Dipakai di dalam angka yang ada lompatan: 一百零五 berarti 105. Goresannya jauh lebih banyak dari angka lain, menarik untuk dilihat digambar."}},{char:"两",pinyin:"liǎng",gloss:{en:"two (before a measure word)",id:"dua (sebelum kata bantu bilangan)"},note:{en:"二 counts, 两 quantifies. 二十 for twenty, but 两个 for two of something - 二个 is simply wrong.",id:"二 untuk menghitung, 两 untuk menyatakan jumlah. 二十 untuk dua puluh, tapi 两个 untuk dua buah - 二个 memang salah."}}],related:[{href:"/blog/kosakata-mandarin-sehari-hari",label:{en:"Everyday vocabulary",id:"Kosakata sehari-hari"}},{href:"/hsk/1",label:{en:"HSK 1 vocabulary",id:"Kosakata HSK 1"}},{href:"/char/%E4%B8%80",label:{en:"Stroke order for 一",id:"Urutan goresan 一"}}]},{slug:"pinyin-adalah",image:{src:"/brand/art/books.webp",alt:{en:"Ink painting of stacked books and a scroll",id:"Lukisan tinta tumpukan buku dan gulungan naskah"}},sources:[{label:"Ujian HSK - situs resmi Chinese Testing International",url:"https://www.chinesetest.cn"},{label:"Daftar kosakata HSK (complete-hsk-vocabulary)",url:"https://github.com/drkameleon/complete-hsk-vocabulary"}],faq:[{q:{en:"What is pinyin?",id:"Apa itu pinyin?"},a:{en:"Pinyin is the official system for writing Mandarin sounds using Latin letters. It is a pronunciation guide rather than the writing system: Chinese people do not read newspapers in pinyin.",id:"Pinyin adalah sistem resmi untuk menulis bunyi bahasa Mandarin dengan huruf Latin. Ia panduan pelafalan, bukan sistem tulisannya: orang Tiongkok tidak membaca koran dalam pinyin."}},{q:{en:"Is pinyin the same as Chinese characters?",id:"Apakah pinyin sama dengan huruf Mandarin?"},a:{en:"No. Pinyin spells the sound; characters carry the meaning. You need pinyin to pronounce a word correctly and characters to read anything real. Learn pinyin first, then characters from the second month.",id:"Bukan. Pinyin mengeja bunyinya; karakter membawa maknanya. Kamu butuh pinyin untuk melafalkan dengan benar dan karakter untuk membaca apa pun yang nyata. Pelajari pinyin dulu, lalu karakter mulai bulan kedua."}},{q:{en:"Which pinyin letters are most often mispronounced?",id:"Huruf pinyin mana yang paling sering salah dibaca?"},a:{en:"Six of them: c is ts not k, q is close to ch, x is close to sh, zh is one sound made with a curled tongue, r is nothing like an Indonesian rolled r, and ü has no Indonesian equivalent. Getting these wrong early means practising the mistake for months.",id:"Ada enam: c dibaca ts bukan k, q dekat ke ch, x dekat ke sh, zh satu bunyi dengan lidah melengkung, r sama sekali bukan r bergetar seperti bahasa Indonesia, dan ü tidak ada padanannya. Salah di awal berarti melatih kesalahan itu berbulan-bulan."}}],date:"2026-08-09",title:{en:"What pinyin is, and the six letters that lie to you",id:"Pinyin adalah apa, dan enam huruf yang menipu"},description:{en:"Pinyin writes Mandarin sounds in Latin letters - but six of them do not say what an Indonesian reader expects. Here is which, and what they actually sound like.",id:"Pinyin menulis bunyi Mandarin dengan huruf Latin - tapi enam di antaranya tidak berbunyi seperti dugaan pembaca Indonesia. Ini daftarnya dan bunyi sebenarnya."},body:{en:"Pinyin is the official system for writing Mandarin sounds in Latin letters. It was adopted in mainland China in 1958, and it is what you type to produce characters on a phone, what dictionaries sort by, and what every beginner course starts with. It is not a translation and it is not an alternative writing system - Chinese is not written in pinyin outside of teaching materials. It is a notation for pronunciation.\n\nThat distinction matters more than it sounds, because it explains the single most common beginner mistake: treating pinyin as a phonetic spelling in your own language. It is not. Pinyin uses Latin letters as arbitrary symbols for Mandarin sounds, and several of them were assigned to sounds that have nothing to do with what the letter does in Indonesian or English.\n\nSix are worth learning explicitly, because getting them wrong now means rehearsing the error for a year.\n\nc is 'ts', not 'k' or 's'. 词 is cí, close to the ts in 'kits'. This is the one that misleads most often.\n\nq is close to 'ch', with the tongue further forward and the lips spread. 请 is qǐng. It is nothing like the q in 'queen'.\n\nx is close to 'sh', again further forward. 西 is xī. Not 'ks', not 'z'.\n\nzh is a single sound, roughly the j in 'jam' but with the tongue curled back. 知 is zhī. The h is not pronounced separately.\n\nr is not the Indonesian rolled r at all. 热 is rè - closer to the s in 'measure', with the tongue curled.\n\nü is a vowel Indonesian does not have: say 'ee' and round your lips without moving your tongue. 女 is nǚ, and 绿 is lǜ. This one needs a mirror more than an explanation.\n\nThere is also a spelling rule that trips people early: after j, q, x and y, the ü loses its dots and is written as plain u. So 去 is written qu but said qü. The u in ju, qu, xu, yu is never the u in bu or lu.\n\nThe practical advice is the same as for tones - do not learn pinyin from a table, learn it from audio. A written explanation of what x sounds like will get you close; hearing 西 said ten times and repeating it will get you there. Every syllable on this site plays, and pinyin is the one part of Mandarin where listening beats reading by the widest margin.",id:"Pinyin adalah sistem resmi untuk menulis bunyi bahasa Mandarin dengan huruf Latin. Diadopsi di Tiongkok daratan pada 1958, dan inilah yang kamu ketik untuk memunculkan karakter di HP, dasar pengurutan kamus, dan awal dari hampir semua kursus pemula. Pinyin bukan terjemahan dan bukan sistem tulisan alternatif - di luar bahan ajar, bahasa Mandarin tidak ditulis dengan pinyin. Ia notasi untuk pelafalan.\n\nPembedaan itu lebih penting daripada kedengarannya, karena menjelaskan kesalahan pemula yang paling umum: menganggap pinyin sebagai ejaan fonetis dalam bahasamu sendiri. Bukan. Pinyin memakai huruf Latin sebagai lambang yang disepakati untuk bunyi Mandarin, dan beberapa di antaranya diberikan pada bunyi yang tidak ada hubungannya dengan bunyi huruf itu dalam bahasa Indonesia.\n\n## Enam huruf pinyin yang menipu\n\nAda enam yang perlu dihafal secara sadar, karena salah sekarang berarti melatih kesalahan itu selama setahun.\n\nc dibaca 'ts', bukan 'k' atau 's'. 词 adalah cí, mirip bunyi ts di akhir kata 'kits'. Inilah yang paling sering menyesatkan.\n\nq dekat ke 'ch', dengan lidah lebih ke depan dan bibir melebar. 请 adalah qǐng. Sama sekali bukan q seperti dalam 'queen'.\n\nx dekat ke 'sh', juga lebih ke depan. 西 adalah xī. Bukan 'ks', bukan 'z'.\n\nzh adalah satu bunyi, kira-kira j dalam 'jam' tapi dengan lidah melengkung ke belakang. 知 adalah zhī. Huruf h-nya tidak dibunyikan terpisah.\n\nr sama sekali bukan r bergetar seperti dalam bahasa Indonesia. 热 adalah rè - lebih dekat ke bunyi s dalam kata Inggris 'measure', dengan lidah melengkung.\n\nü adalah vokal yang tidak ada dalam bahasa Indonesia: ucapkan 'i' lalu bulatkan bibir tanpa menggerakkan lidah. 女 adalah nǚ, dan 绿 adalah lǜ. Yang ini lebih butuh cermin daripada penjelasan.\n\n## Aturan penulisan pinyin yang membingungkan\n\nAda juga aturan penulisan yang cepat membingungkan: setelah j, q, x, dan y, ü kehilangan titiknya dan ditulis u biasa. Jadi 去 ditulis qu tapi dibaca qü. Huruf u dalam ju, qu, xu, yu tidak pernah sama dengan u dalam bu atau lu.\n\n## Cara belajar pinyin yang benar\n\nSaran praktisnya sama seperti untuk nada - jangan belajar pinyin dari tabel, belajarlah dari audio. Penjelasan tertulis tentang bunyi x akan membawamu mendekat; mendengar 西 diucapkan sepuluh kali lalu menirukannya akan membawamu sampai. Setiap suku kata di situs ini bisa diputar, dan pinyin adalah bagian bahasa Mandarin di mana mendengar mengalahkan membaca dengan selisih paling lebar."},demos:[{char:"词",pinyin:"cí",gloss:{en:"word",id:"kata"},note:{en:"c is 'ts'. Play it - the gap between what the letter suggests and what it says is wider here than anywhere else in pinyin.",id:"c dibaca 'ts'. Putar audionya - jarak antara dugaan dari hurufnya dan bunyi sebenarnya paling lebar di sini."}},{char:"请",pinyin:"qǐng",gloss:{en:"please",id:"tolong"},note:{en:"q, close to 'ch' with the tongue forward and lips spread. Compare it against 吃 below, which is the tongue-back version.",id:"q, dekat ke 'ch' dengan lidah maju dan bibir melebar. Bandingkan dengan 吃 di bawah, yang versi lidah mundur."}},{char:"吃",pinyin:"chī",gloss:{en:"to eat",id:"makan"},note:{en:"ch, the retroflex pair to q. Same family of sound, tongue curled back. Hearing them next to each other is the fastest way to separate them.",id:"ch, pasangan retrofleks dari q. Keluarga bunyi yang sama, lidah melengkung ke belakang. Mendengarnya berdampingan cara tercepat memisahkannya."}},{char:"西",pinyin:"xī",gloss:{en:"west",id:"barat"},note:{en:"x, close to 'sh'. Not 'ks' - the letter is doing a job it never does in Indonesian.",id:"x, dekat ke 'sh'. Bukan 'ks' - hurufnya menjalankan tugas yang tidak pernah ia jalankan dalam bahasa Indonesia."}},{char:"热",pinyin:"rè",gloss:{en:"hot",id:"panas"},note:{en:"r, and nothing like the Indonesian rolled r. Closer to the s in 'measure', tongue curled.",id:"r, dan sama sekali tidak seperti r bergetar bahasa Indonesia. Lebih dekat ke bunyi s dalam 'measure', lidah melengkung."}},{char:"女",pinyin:"nǚ",gloss:{en:"woman",id:"perempuan"},note:{en:"ü - say 'ee' and round your lips without moving your tongue. Indonesian has no such vowel, so this one needs a mirror.",id:"ü - ucapkan 'i' lalu bulatkan bibir tanpa menggerakkan lidah. Bahasa Indonesia tidak punya vokal ini, jadi yang satu ini butuh cermin."}}],related:[{href:"/pinyin",label:{en:"Pinyin trainer",id:"Latihan pinyin"}},{href:"/blog/nada-mandarin",label:{en:"Mandarin tones",id:"Nada Mandarin"}},{href:"/blog/belajar-mandarin-dari-nol",label:{en:"Learning from zero",id:"Belajar dari nol"}}]}];a.s(["BLOG",0,n,"findPost",0,function(a){return n.find(n=>n.slug===a)}])}]);